import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"1999年 · 认清能力边界","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1999年.md","filePath":"05_quotes/by-year/1999年.md"}'),r={name:"05_quotes/by-year/1999年.md"};function s(c,e,h,u,_,i){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_1999年-·-认清能力边界" tabindex="-1">1999年 · 认清能力边界 <a class="header-anchor" href="#_1999年-·-认清能力边界" aria-label="Permalink to &quot;1999年 · 认清能力边界&quot;">​</a></h1><blockquote><p>我们不持有科技公司的股票，因为我们无法以很高的确信度判断哪些科技领域的参与者拥有真正持久的竞争优势。——巴菲特（69岁）</p></blockquote><p>本页收录1999年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>预测下雨不算数；建造方舟才算数。（2001年补充）<em>——此理念贯穿1999年的投资反思</em></p></blockquote><blockquote><p>真正引起我们注意的是以合理价格买入优秀企业。</p></blockquote><blockquote><p>如果你要在合理价格买入平庸企业，或在可疑价格买入优秀企业之间做出选择，我们更倾向于后者。</p></blockquote><blockquote><p>我们从未试图预测股票市场在接下来的一个月或一年会做什么。</p></blockquote><blockquote><p>如果我们有什么优势的话，那就是认识到我们何时在能力圈内良好运作，何时接近能力圈的边界。</p></blockquote><blockquote><p>我们只坚持我们理解的东西。如果我们偏离了，那将是不小心的，而不是因为焦躁不安、用希望替代了理性。</p></blockquote><blockquote><p>其他人可能会模仿我们的模式，但他们无法复制我们的经济。</p></blockquote><blockquote><p>只有一种事实组合使公司回购其股票成为明智之举：首先，公司有可用资金——现金加上合理的借贷能力——超出了业务的近期需求；其次，发现其股票在市场上以低于保守计算的内在价值的价格出售。</p></blockquote><blockquote><p>以1.10美元的价格购买1美元钞票，对于留下来的人来说不是好生意。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1999年是巴菲特执掌伯克希尔以来绝对表现和相对表现最差的一年：净值仅增长0.5%，而标普500指数同期上涨21%，落后幅度达20.5个百分点。巴菲特将原因归结为自己在资本配置上的失误，主要持仓股普遍表现落后。他同时承认，对科技行业缺乏真正的洞察力，因此选择不参与。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1999年-翻译-·-01-letters-1999年-核心总结-·-01-letters-1999年-思维导图" tabindex="-1"><a href="/01_letters/1999年/翻译.html">01_letters/1999年/翻译</a> · <a href="/01_letters/1999年/核心总结.html">01_letters/1999年/核心总结</a> · <a href="/01_letters/1999年/思维导图.html">01_letters/1999年/思维导图</a> <a class="header-anchor" href="#_01-letters-1999年-翻译-·-01-letters-1999年-核心总结-·-01-letters-1999年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1999年/翻译]] · [[→ 核心总结|01_letters/1999年/核心总结]] · [[→ 思维导图|01_letters/1999年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1999年/翻译.html">/01_letters/1999年/翻译</a></li></ul>',22)])])}const q=t(r,[["render",s]]);export{p as __pageData,q as default};
